import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { FileRow, View } from '../types'

const COMMAND = 'commit'
const PANE = 'cc-commit-command'
const view = atom({ plugin: 'cc-commit-command', key: 'view' } as const, { files: [], message: '', note: '' } as View)

const SUBMIT = 'Commit'
const REGENERATE = 'Regenerate'
const EDIT = 'Edit in editor'
const CANCEL = 'Cancel'

const SENSITIVE = /(^|\/)\.env($|\.)|\.(pem|key|p12)$|credential|secret/i
const DIFF_LIMIT = 40_000

const RULES = `- message uses Conventional Commits: <type>(<scope>): <subject>; for larger changes add a body after a blank line; type is one of feat, fix, docs, style, refactor, perf, test, build, ci, chore
- Match the language and style of the recent commits
- Describe only the changes in files; no attribution lines (such as Co-Authored-By)
- Output only one JSON object {"files": [...], "message": "..."}, with no code fence or explanation`

type Change = { status: string; path: string }
type Plan = { files: string[]; message: string }
type Repo = {
  all: Change[]
  // Only the staged files when the index is non-empty, otherwise all changes
  candidates: Change[]
  isStaged: boolean
  branch: string
  log: string
  diff: string
  // What the plan was drafted from: HEAD, and the tree of the index (staged) or of HEAD plus the candidates (otherwise)
  head: string
  tree: string
}
// adjust: new instructions given, so revise the previous version; otherwise produce a clearly different one
type Request = Repo & { guidance: string; previous?: string; adjust?: boolean }
type Reply = { isAnswered: boolean; text?: string; reason?: string }

// Set on session.start
let home = ''
let cwd = ''

function git($: EngineInterface, root: string, args: string[]) {
  return $.process.run(['git', ...args], { cwd: root })
}

// Runs git against a throwaway index file, so the shared index other sessions stage into is never read or written
async function withIndex<T>(
  $: EngineInterface,
  root: string,
  fn: (run: (args: string[]) => ReturnType<typeof git>, file: string) => Promise<T>,
): Promise<T> {
  const path = (await git($, root, ['rev-parse', '--git-path', `cc-commit-command-${Date.now()}.index`])).stdout.trim()
  const file = path.startsWith('/') ? path : `${root}/${path}`
  try {
    return await fn(args => $.process.run(['git', ...args], { cwd: root, env: { GIT_INDEX_FILE: file } }), file)
  } finally {
    await $.process.run(['rm', '-f', file])
  }
}

const readHead = (head: string) => (head ? ['read-tree', head] : ['read-tree', '--empty'])

const tail = (text: string, lines: number) => text.trim().split('\n').slice(-lines).join('\n')

// -z format: each entry is "XY path"; renames and copies are followed by an extra entry with the original path
function parseStatus(output: string): Change[] {
  const parts = output.split('\0').filter(Boolean)
  const changes: Change[] = []
  for (let i = 0; i < parts.length; i++) {
    const entry = parts[i] ?? ''
    const status = entry.slice(0, 2)
    changes.push({ status, path: entry.slice(3) })
    if (status[0] === 'R' || status[0] === 'C') i++
  }
  return changes
}

async function snapshot(
  $: EngineInterface,
  root: string,
  isStaged: boolean,
  candidates: Change[],
): Promise<{ head: string; tree: string } | string> {
  const head = (await git($, root, ['rev-parse', '-q', '--verify', 'HEAD'])).stdout.trim()
  const written = isStaged
    ? await git($, root, ['write-tree'])
    : await withIndex($, root, async run => {
        for (const args of [readHead(head), ['add', '-A', '--', ...candidates.map(change => change.path)]]) {
          const step = await run(args)
          if (step.exitCode !== 0) return step
        }
        return run(['write-tree'])
      })
  if (written.exitCode !== 0) return `Reading the changes failed: ${tail(written.stderr, 3)}`
  return { head, tree: written.stdout.trim() }
}

async function collect($: EngineInterface, root: string): Promise<Repo | string> {
  const all = parseStatus(
    (await git($, root, ['status', '--porcelain=v1', '-z', '--untracked-files=all'])).stdout,
  )
  const staged = all.filter(change => change.status[0] !== ' ' && change.status[0] !== '?')
  const isStaged = staged.length > 0
  const branch = (await git($, root, ['branch', '--show-current'])).stdout.trim() || 'HEAD'
  const log = (await git($, root, ['log', '--oneline', '-10'])).stdout.trim()
  let diff = (await git($, root, isStaged ? ['diff', '--cached'] : ['diff'])).stdout
  if (!isStaged)
    for (const change of all.filter(change => change.status === '??').slice(0, 20))
      diff += (await git($, root, ['diff', '--no-index', '--', '/dev/null', change.path])).stdout
  if (diff.length > DIFF_LIMIT) diff = `${diff.slice(0, DIFF_LIMIT)}\n… (diff too long, truncated)`
  const candidates = isStaged ? staged : all
  const taken = await snapshot($, root, isStaged, candidates)
  if (typeof taken === 'string') return taken
  return { all, candidates, isStaged, branch, log, diff, ...taken }
}

const contextOf = (r: Request) => `<repo>
Branch: ${r.branch}
Recent commits:
${r.log || '(no commits yet)'}
</repo>

<candidates>
${r.candidates.map(change => `${change.status} ${change.path}`).join('\n')}
</candidates>

<diff>
${r.diff}
</diff>${
  r.guidance
    ? `\n\nUser instructions for this commit (may add or remove files or rewrite the message):\n<guidance>\n${r.guidance}\n</guidance>`
    : ''
}${
  r.previous
    ? `\n\n${r.adjust ? 'This is the previous commit message; revise it according to <guidance>' : 'The user was not satisfied with the previous commit message; produce a clearly different version'}:\n<previous>\n${r.previous}\n</previous>`
    : ''
}`

const forkPromptOf = (r: Request) => `This turn is not a new task: do not continue earlier work; only prepare one commit for the git changes below and output JSON as required.
${
  r.isStaged
    ? '- files: the index is already chosen; return every file in <candidates> as is'
    : '- files: pick from <candidates> the files this session changed, based on the edits and writes earlier in the conversation; skip files with no change record in the conversation, since they may come from other sessions or manual edits; files that <guidance> explicitly adds or removes follow <guidance>'
}
- files excludes likely sensitive files (.env, keys, credentials) unless <guidance> explicitly asks for them
${RULES}

${contextOf(r)}`

const SYSTEM = `You write commit messages for git changes.
- files returns every file in <candidates> as is
${RULES}`

function parsePlan(text: string, paths: string[]): Plan | undefined {
  try {
    const raw = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1)) as {
      files?: unknown
      message?: unknown
    }
    if (typeof raw.message !== 'string' || !Array.isArray(raw.files)) return undefined
    const files = raw.files.filter((file): file is string => typeof file === 'string' && paths.includes(file))
    return { files, message: raw.message.trim() }
  } catch {
    return undefined
  }
}

// The fork carries session context, so it can tell which files this session changed; with no conversation yet, fall back to sonnet, which sees only the diff
async function generate($: EngineInterface, r: Request): Promise<{ plan: Plan; note: string } | string> {
  const paths = r.candidates.map(change => change.path)
  const forked = (await $.model.fork({ prompt: forkPromptOf(r) })) as Reply
  const hasContext = forked.reason !== 'nothing-to-fork'
  const reply = hasContext
    ? forked
    : ((await $.model.complete({ model: 'sonnet', system: SYSTEM, prompt: contextOf(r) })) as Reply)
  if (!reply.isAnswered || !reply.text) return `Generation failed: ${reply.reason ?? 'the model returned nothing'}`
  const plan = parsePlan(reply.text, paths)
  if (!plan) return `Generation failed: the model did not return the expected format\n${tail(reply.text, 3)}`

  const notes: string[] = []
  if (r.isStaged) {
    plan.files = paths
    notes.push('Index already has staged changes: committing only the index')
  } else if (!hasContext) {
    plan.files = paths.filter(path => !SENSITIVE.test(path))
    notes.push('No session context: selected all changes (except likely sensitive files); please review')
  }
  if (plan.files.some(path => SENSITIVE.test(path))) notes.push('⚠ Selected files include likely sensitive files')
  return { plan, note: notes.join('\n') }
}

async function editMessage($: EngineInterface, message: string): Promise<{ message: string; error?: string }> {
  const dir = `${home}/.claude/cache/cc-commit-command`
  const file = `${dir}/COMMIT_EDITMSG`
  await $.process.run(['mkdir', '-p', dir])
  await $.fs.write(file, `${message}\n\n# Save and close to return to the confirm dialog; lines starting with # are ignored; an empty message keeps the original\n`)
  // When EDITOR waits for close (e.g. zed --wait), this step blocks until the editor closes
  const edited = await $.process.run(['/bin/sh', '-c', '${VISUAL:-${EDITOR:-vi}} "$0"', file], {
    timeoutMs: 600_000,
  })
  if (edited.exitCode !== 0) return { message, error: `Editor exited with code ${edited.exitCode}: ${tail(edited.stderr, 2)}` }
  const text = (await $.fs.read(file))
    .split('\n')
    .filter(line => !line.startsWith('#'))
    .join('\n')
    .trim()
  return { message: text || message }
}

// Commits exactly the reviewed content from a private index: the staged tree as a whole, or the plan's files from the
// candidates' tree on top of HEAD. Staging done meanwhile in the shared index stays out of the commit and stays staged.
async function commit($: EngineInterface, root: string, repo: Repo, plan: Plan) {
  return withIndex($, root, async (run, file) => {
    const steps = repo.isStaged
      ? [['read-tree', repo.tree]]
      : [readHead(repo.head), ['reset', '-q', repo.tree, '--', ...plan.files]]
    for (const args of steps) {
      const step = await run(args)
      if (step.exitCode !== 0) return { error: `Staging failed: ${tail(step.stderr, 3)}` }
    }
    // $.process.run disables repo hooks when running git directly; going through sh runs pre-commit and other hooks
    const done = await $.process.run(['/bin/sh', '-c', 'git commit -F -'], {
      cwd: root,
      env: { GIT_INDEX_FILE: file },
      stdin: plan.message,
      timeoutMs: 600_000,
    })
    if (done.exitCode !== 0) return { error: `Commit failed:\n${tail(done.stderr || done.stdout, 5)}` }
    // The shared index still holds the old content of the committed files; move them up to the new HEAD
    if (!repo.isStaged) await git($, root, ['reset', '-q', '--', ...plan.files])
    return { hash: (await git($, root, ['rev-parse', '--short', 'HEAD'])).stdout.trim() }
  })
}

const rowsOf = (repo: Repo, plan: Plan | undefined): FileRow[] =>
  repo.all.map(change => ({
    ...change,
    isSelected: plan?.files.includes(change.path) ?? false,
    isSensitive: SENSITIVE.test(change.path),
  }))

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    home = (await $.env.get('HOME')) ?? ''
    cwd = e.cwd
    // No immediate: mid-turn the model may still be editing files, so wait for the turn to end before committing
    await $.command.register({
      name: COMMAND,
      description: 'Draft a commit plan, confirm it in a dialog, then commit',
      argumentHint: '[instructions]',
    })
    return next(e)
  })

  // Intermediate steps go only to the pane, confirm dialog and status line; the returned text is the only result line in the transcript
  on('command.run', { command: COMMAND }, async ($, e) => {
    const top = await $.process.run(['git', 'rev-parse', '--show-toplevel'], { cwd })
    if (top.exitCode !== 0) return { text: 'Not committed: current directory is not a git repository' }
    const root = top.stdout.trim()
    const first = await collect($, root)
    if (typeof first === 'string') return { text: `Not committed: ${first}` }
    if (first.all.length === 0) return { text: 'Not committed: no changes' }
    let repo = first

    let request: Request = { ...repo, guidance: e.args.trim() }
    let plan: Plan | undefined
    let note = ''
    let notice = ''
    let needsPlan = true
    try {
      for (;;) {
        if (needsPlan) {
          needsPlan = false
          $.ui.status('Drafting commit plan…')
          const generated = await generate($, request)
          $.ui.status(undefined)
          if (typeof generated === 'string') note = generated
          else ({ plan, note } = generated)
          note = [notice, note].filter(Boolean).join('\n')
          notice = ''
        }
        await update($, view, () => ({ files: rowsOf(repo, plan), message: plan?.message ?? '', note }))
        await $.ui.open({ id: PANE, title: `commit · ${repo.branch}` })

        const answer = await $.ui
          .ask('What would you like to do with this commit?', { header: 'commit', options: [SUBMIT, REGENERATE, EDIT, CANCEL] })
          .catch(() => CANCEL)
        if (answer === CANCEL) return { text: 'Cancelled, nothing committed' }
        if (answer === REGENERATE) {
          request = { ...request, previous: plan?.message, adjust: false }
          needsPlan = true
        } else if (answer === EDIT) {
          if (!plan) continue
          const edited = await editMessage($, plan.message)
          plan = { ...plan, message: edited.message }
          note = edited.error ?? note
        } else if (answer === SUBMIT) {
          if (!plan || plan.files.length === 0 || !plan.message) {
            note = 'No files or commit message to commit'
            continue
          }
          // A snapshot that no longer reads (a candidate gone from disk) has moved too. Unstaged, only the plan's files
          // count, so another session editing some other file does not send the plan back.
          const now = await snapshot($, root, repo.isStaged, repo.candidates)
          const hasMoved =
            typeof now === 'string' ||
            now.head !== repo.head ||
            (repo.isStaged
              ? now.tree !== repo.tree
              : (await git($, root, ['diff-tree', '--quiet', repo.tree, now.tree, '--', ...plan.files])).exitCode !== 0)
          if (hasMoved) {
            const fresh = await collect($, root)
            if (typeof fresh === 'string') return { text: `Not committed: ${fresh}` }
            if (fresh.all.length === 0) return { text: 'Not committed: no changes' }
            repo = fresh
            request = { ...fresh, guidance: request.guidance }
            notice = 'Changes moved since the plan; drafted again'
            needsPlan = true
            continue
          }
          const result = await commit($, root, repo, plan)
          if ('hash' in result) {
            const subject = plan.message.split('\n')[0]
            return { text: `Committed ${result.hash} ${subject} (${plan.files.length} ${plan.files.length === 1 ? 'file' : 'files'})` }
          }
          note = result.error
        } else {
          // The dialog's Other option: revision instructions typed by the user
          const guidance = [request.guidance, answer].filter(Boolean).join('; ')
          request = { ...request, guidance, previous: plan?.message, adjust: true }
          needsPlan = true
        }
      }
    } finally {
      $.ui.status(undefined)
      await $.ui.close({ id: PANE })
    }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text } = $.ui.resolve(e)
    const { files, message, note } = await read($, view)
    const selected = files.filter(file => file.isSelected)
    const skipped = files.filter(file => !file.isSelected)
    const rowOf = (file: FileRow) => `  ${file.status} ${file.path}${file.isSensitive ? '  ⚠ likely sensitive' : ''}`
    return (
      <Box flexDirection="column">
        <Text bold>{`To commit (${selected.length})`}</Text>
        {selected.map(file => (
          <Text>{rowOf(file)}</Text>
        ))}
        {skipped.length > 0 && <Text bold>{`Not committed (${skipped.length})`}</Text>}
        {skipped.map(file => (
          <Text dimColor>{rowOf(file)}</Text>
        ))}
        <Text> </Text>
        {(message || '(no commit message yet)').split('\n').map(line => (
          <Text>{line || ' '}</Text>
        ))}
        {note && <Text> </Text>}
        {note &&
          note.split('\n').map(line => (
            <Text color="yellow">{line}</Text>
          ))}
      </Box>
    )
  })
}

