files.types/index.d.ts:
export type FileRow = { status: string; path: string; isSelected: boolean; isSensitive: boolean }

export type View = {
  files: FileRow[]
  message: string
  // Hint at the bottom of the pane: no session context, commit failure reason, etc.
  note: string
}

declare module 'claude-code' {
  interface PluginState {
    'cc-commit-command': { view: View }
  }
}
